/**
 * Spawn bands by campaign order (pure), generated by tools/playthrough/bands.ts:
 * - School realms (zoneBands.gen.ts): a side's zones and the roads out to them start at the expected hero level of
 *   their first visit and step up at later visits. A tier applies once Act I main quest `step` is done by the
 *   side's own class or by the host's class (a sibling class, or any co-op host, still sees the side grow).
 * - Concordia (concordiaBands.gen.ts): per Morvane region, keyed by the host's class (each class thread visits the
 *   regions in its own order); tiers step with that host's Act II/III main quests. No host class (public realms):
 *   the Act II midpoint, L20 (the Heart L30).
 * Groups the tables don't know keep their old fixed band (`fallback`).
 */
import { ACT1_MAINS, SIDE_CLASS, ZONE_BANDS, type ZoneTier } from '@/data/regions/hc/zoneBands.gen';
import { ACT23_MAINS, CONCORDIA_BANDS } from '@/data/regions/hc/concordiaBands.gen';

/** A level band that applies once main quest `step` (1-based, of the band's track) is done (later tiers win). */
export interface LevelTier { step: number; level: [number, number]; elite?: boolean }
interface Band { level: [number, number]; elite?: boolean; tiers?: LevelTier[] }
export interface Banded extends Band {
  /** realm sides: the class whose campaign plays it */
  cls?: string;
  /** which main-quest list `step` counts in: Act I (realms) or Acts II–III (Concordia) */
  track?: 'act1' | 'act23';
  /** Concordia: the band per host class (the base band is the public-realm one) */
  byClass?: Record<string, Band>;
}
/** whether main quest `step` of `track` is done by `cls` (the side's class, or the host) */
export type StepDone = (cls: string | undefined, step: number, track: 'act1' | 'act23') => boolean;

/** patrols and camps lead elites only from this level (Claude 3: no elite walls below ~L8) */
const ELITE_FROM = 8;
type Kind = 'zone' | 'patrol' | 'camp-near' | 'camp' | 'guard' | 'pack';

/** The zone-number floor (zone 2 → L1, 3 → L5, 4 → L9). */
export const zoneFloor = (zone: number): number => Math.max(1, 1 + (zone - 2) * 4);

function one(kind: Kind, f: number, eliteGuard: boolean): { level: [number, number]; elite?: boolean } {
  switch (kind) {
    case 'zone': return { level: [f, f + 2] };
    case 'patrol': return { level: [f + 1, f + 2], elite: f + 1 >= ELITE_FROM };
    case 'camp-near': return { level: [Math.max(1, f - 1), Math.max(1, f - 1) + 1] };
    case 'guard': return { level: [f, f + 1], elite: eliteGuard && f >= ELITE_FROM };
    case 'pack': return { level: [f + 1, f + 2], elite: true };
    default: return { level: [f, f + 1] };
  }
}

function band(tiers: ZoneTier[], kind: Kind, eliteGuard: boolean): Band {
  const [first, ...rest] = tiers;
  return { ...one(kind, first.floor, eliteGuard), tiers: rest.length ? rest.map((t) => ({ step: t.step!, ...one(kind, t.floor, eliteGuard) })) : undefined };
}

/**
 * Level (and elite) of a realm spawn in `group` (zone n of a side, a realm's gate road, an optional area's
 * approach). `eliteGuard`: an approach guard that leads with an elite once its floor reaches L8. `alt`: when no
 * walk reaches the group (optional areas are off every quest route), follow that group's tiers `step` levels up
 * (the zone beside it) instead of the fixed fallback.
 */
export function banded(group: string, fallback: number, kind: Kind, eliteGuard = false, alt?: { group: string; step: number }): Banded {
  const cls = SIDE_CLASS[group.split('-').slice(0, 2).join('-')];
  const near = alt && ZONE_BANDS[alt.group]?.map((t) => ({ ...t, floor: Math.min(12, t.floor + alt.step) }));
  return { ...band(ZONE_BANDS[group] ?? near ?? [{ floor: Math.max(1, fallback) }], kind, eliteGuard), cls, track: 'act1' };
}

/** Level (and elite) of a Concordia spawn in a Morvane region, per host class. */
export function concordiaBanded(region: string, fallback: number, kind: Kind, eliteGuard = false): Banded {
  const classes = Object.keys(CONCORDIA_BANDS);
  // public realms (no host class): the Act II midpoint; before the table is generated: the handoff band
  const pub = classes.length ? (region === 'region:heart' ? 30 : 20) : fallback;
  const byClass: Record<string, Band> = {};
  for (const c of classes) { const t = CONCORDIA_BANDS[c][region]; if (t) byClass[c] = band(t, kind, eliteGuard); }
  return { ...one(kind, pub, eliteGuard), track: 'act23', byClass: classes.length ? byClass : undefined };
}

/** The tier in force: the host's own band (Concordia), then the last tier whose step is done. */
function current(z: Banded, done: StepDone, host: string | null): { level: [number, number]; elite?: boolean } {
  const b: Band = (host && z.byClass?.[host]) || z;
  const who = z.byClass ? host ?? undefined : z.cls;
  let t: { level: [number, number]; elite?: boolean } = b;
  for (const x of b.tiers ?? []) if (done(who, x.step, z.track ?? 'act1')) t = x;
  return t;
}

/** The level band in force for a spawn zone (host: the campaign owner's class, if any). */
export const levelAt = (z: Banded, done: StepDone, host: string | null = null): [number, number] => current(z, done, host).level;
/** Whether a spawn zone leads with an elite now. */
export const eliteAt = (z: Banded, done: StepDone, host: string | null = null): boolean => !!current(z, done, host).elite;

/** The live StepDone: that main quest is completed by `cls` or by the host's class. */
export function stepDone(host: string | null, completed: (quest: string) => boolean): StepDone {
  return (cls, step, track) => [cls, host].some((c) => {
    const q = c ? (track === 'act23' ? ACT23_MAINS : ACT1_MAINS)[c]?.[step - 1] : undefined;
    return !!q && completed(q);
  });
}
